CREATE TABLE usuarios (id BIGINT AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(255) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, telefono VARCHAR(255) NOT NULL, password VARCHAR(255) NOT NULL, rol VARCHAR(255) NOT NULL, fecha_registro DATETIME(6));
CREATE TABLE servicios (id BIGINT AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(255) NOT NULL UNIQUE, descripcion VARCHAR(300) NOT NULL, icono VARCHAR(255) NOT NULL, precio_unitario DECIMAL(8,2) NOT NULL, recargo_color DECIMAL(8,2) NOT NULL, permite_doble_cara BOOLEAN NOT NULL);
CREATE TABLE contactos (id BIGINT AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(255) NOT NULL, email VARCHAR(255) NOT NULL, telefono VARCHAR(255), mensaje VARCHAR(1000) NOT NULL, fecha_envio DATETIME(6));
CREATE TABLE pedidos (id BIGINT AUTO_INCREMENT PRIMARY KEY, usuario_id BIGINT NOT NULL, servicio_id BIGINT NOT NULL, cantidad INT NOT NULL, a_color BOOLEAN NOT NULL, doble_cara BOOLEAN NOT NULL, notas VARCHAR(500), total DECIMAL(10,2) NOT NULL, estado VARCHAR(255) NOT NULL, fecha DATETIME(6) NOT NULL, FOREIGN KEY (usuario_id) REFERENCES usuarios(id), FOREIGN KEY (servicio_id) REFERENCES servicios(id));
